create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,username text not null unique,phone text,country text,company_name text,avatar_url text,role text not null default 'user' check(role in('user','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.templates(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,description text,preview_url text,is_published boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.websites(id uuid primary key default gen_random_uuid(),owner_id uuid not null unique references public.profiles(id) on delete cascade,template_id uuid references public.templates(id) on delete set null,site_name text,headline text,bio text,status text not null default 'draft' check(status in('draft','published','suspended')),subdomain text not null unique,seo_title text,seo_description text,og_image_url text,favicon_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),website_id uuid not null references public.websites(id) on delete cascade,title text not null,description text,image_url text,technology text,project_url text,github_url text,sort_order integer not null default 0);
create table if not exists public.services(id uuid primary key default gen_random_uuid(),website_id uuid not null references public.websites(id) on delete cascade,title text not null,description text,icon text,sort_order integer not null default 0);
create table if not exists public.skills(id uuid primary key default gen_random_uuid(),website_id uuid not null references public.websites(id) on delete cascade,name text not null,level integer check(level between 0 and 100),sort_order integer not null default 0);
create table if not exists public.domains(id uuid primary key default gen_random_uuid(),website_id uuid not null references public.websites(id) on delete cascade,hostname text not null unique,status text not null default 'pending' check(status in('pending','verifying','verified','active','failed')),verification_token text not null,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.websites enable row level security;alter table public.projects enable row level security;alter table public.services enable row level security;alter table public.skills enable row level security;alter table public.domains enable row level security;
drop policy if exists "profiles_self" on public.profiles;
drop policy if exists "websites_owner" on public.websites;
drop policy if exists "projects_owner" on public.projects;
drop policy if exists "services_owner" on public.services;
drop policy if exists "skills_owner" on public.skills;
drop policy if exists "domains_owner" on public.domains;
create policy "profiles_self" on public.profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy "websites_owner" on public.websites for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "projects_owner" on public.projects for all using(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid())) with check(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid()));
create policy "services_owner" on public.services for all using(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid())) with check(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid()));
create policy "skills_owner" on public.skills for all using(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid())) with check(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid()));
create policy "domains_owner" on public.domains for all using(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid())) with check(exists(select 1 from public.websites w where w.id=website_id and w.owner_id=auth.uid()));